/**
 * Suite sources for the offline eval gate (ENG-2145). Each turns one kind of case into metric
 * observations for offlineSuite.ts:
 *
 * - failureReplaySource: the ENG-591 registered replay cases, per grader (deterministic).
 * - replayFixtureSource: the ENG-1312 reply-length fixtures. The recorded replies are
 *   deterministic; with a candidate runner (staging) each reply is regenerated by the candidate
 *   prompt/model and the metric becomes probabilistic.
 * - goldenSetSource: grader agreement with human labels on the ENG-2135 golden set (test split),
 *   once the store is provisioned (OPS-2, ENG-2147).
 * - The Okareo source lives in okareoClient.ts.
 *
 * Sources report `not_configured` for something that is not set up, and throw or return `failed`
 * for something that is set up and broken; the suite turns both into fail-closed verdicts when
 * the baseline expects their metrics.
 */

import { AGENT_GRADER_VERSIONS, type AgentGraderId } from './agentGraders';
import { checkReplayFixture, REPLAY_FIXTURES, type JudgeReplayFixture } from './agentModeReplayFixtures';
import { loadReplayFixtures, type LoadedReplayFixtures } from './agentModeReplayFixtureSource';
import { evaluateReplayCase } from './failureReplaySuite';
import { FAILURE_REPLAY_CATALOG, runRegisteredCheck, toFailureReplayCases, type RegisteredReplayCase } from './failureReplayCatalog';
import { isAiLabelled } from './goldenSet';
import type { GoldenSetStore } from './goldenSetStore';
import type { MetricObservation, SuiteSource } from './offlineSuite';
import { computeCriterionAgreement, type GoldenCaseGrader, type GraderPrediction } from './runValidation';

/** Eval-registry id of the ENG-1312 reply-length fixture checker. */
export const REPLY_LENGTH_FIXTURES_GRADER = 'agent-reply-length-fixtures';
/** Bump when checkReplayFixture's rules change. */
export const REPLY_LENGTH_FIXTURES_VERSION = 1;
/** Version tag for adapters over judges' stored verdicts (the judge prompt/model is AW-Settings state). */
export const STORED_VERDICT_VERSION = 'stored';

function isAgentGraderId(id: string): id is AgentGraderId {
  return id in AGENT_GRADER_VERSIONS;
}

/** The version string recorded for a grader in a baseline. */
export function graderVersionOf(graderId: string): string {
  if (isAgentGraderId(graderId)) return String(AGENT_GRADER_VERSIONS[graderId]);
  if (graderId === REPLY_LENGTH_FIXTURES_GRADER) return String(REPLY_LENGTH_FIXTURES_VERSION);
  return STORED_VERDICT_VERSION;
}

export function failureReplaySource(catalog: readonly RegisteredReplayCase[] = FAILURE_REPLAY_CATALOG): SuiteSource {
  return {
    id: 'failure-replay',
    async run() {
      const byGrader = new Map<string, { n: number; passes: number; failures: string[] }>();
      const replayCases = toFailureReplayCases(catalog);
      for (const [i, registered] of catalog.entries()) {
        const result = await evaluateReplayCase(replayCases[i], runRegisteredCheck);
        const tally = byGrader.get(registered.graderId) ?? { n: 0, passes: 0, failures: [] };
        tally.n++;
        if (result.passed) tally.passes++;
        else tally.failures.push(result.error ? `${result.caseId} (threw: ${result.error})` : result.caseId);
        byGrader.set(registered.graderId, tally);
      }
      const observations: MetricObservation[] = [...byGrader.entries()].map(([graderId, t]) => ({
        metricId: `failure-replay:${graderId}`,
        graderId,
        graderVersion: graderVersionOf(graderId),
        kind: 'deterministic',
        category: 'quality',
        n: t.n,
        passes: t.passes,
        placeholder: false,
        failures: t.failures,
      }));
      return { source: 'failure-replay', status: 'ok', observations, notes: [`${catalog.length} registered case(s)`] };
    },
  };
}

/** Regenerates a fixture's assistant reply with the candidate prompt/model (a staging call). */
export type CandidateReplyRunner = (fixture: JudgeReplayFixture) => Promise<string>;

export function replayFixtureSource(opts: {
  load?: () => Promise<LoadedReplayFixtures>;
  candidate?: CandidateReplyRunner;
} = {}): SuiteSource {
  const load = opts.load ?? (async () => ({ fixtures: [...REPLAY_FIXTURES], notes: ['golden-set store not consulted: synthetic placeholders'] }));
  return {
    id: 'replay-fixtures',
    async run() {
      const { fixtures, notes } = await load();
      const gated = fixtures.filter((f) => !f.pending);
      let passes = 0;
      const failures: string[] = [];
      for (const fixture of gated) {
        let checked = fixture;
        if (opts.candidate) {
          const userTurns = fixture.turns.filter((t) => t.role === 'user');
          checked = { ...fixture, turns: [...userTurns, { role: 'assistant', content: await opts.candidate(fixture) }] };
        }
        const result = checkReplayFixture(checked);
        if (result.pass) passes++;
        else failures.push(fixture.id);
      }
      const pending = fixtures.length - gated.length;
      const observation: MetricObservation = {
        metricId: opts.candidate ? 'replay-fixture-length:candidate' : 'replay-fixture-length',
        graderId: REPLY_LENGTH_FIXTURES_GRADER,
        graderVersion: String(REPLY_LENGTH_FIXTURES_VERSION),
        kind: opts.candidate ? 'probabilistic' : 'deterministic',
        category: 'quality',
        n: gated.length,
        passes,
        placeholder: gated.length > 0 && gated.every((f) => f.isPlaceholder),
        failures,
      };
      return {
        source: 'replay-fixtures',
        status: 'ok',
        observations: [observation],
        notes: [...notes, ...(pending > 0 ? [`${pending} fixture(s) pending a numeric threshold, not gated`] : [])],
      };
    },
  };
}

/** Human-label agreement per golden-case grader on the test split (observed agreement, n pairs). */
export function goldenSetSource(opts: { store: GoldenSetStore; graders: () => readonly GoldenCaseGrader[] }): SuiteSource {
  return {
    id: 'golden-set',
    async run() {
      if (!opts.store.isProvisioned()) {
        return { source: 'golden-set', status: 'not_configured', reason: 'golden-set store not provisioned (EVAL_GOLDEN_CASES_TABLE, OPS-2 ENG-2147)' };
      }
      const observations: MetricObservation[] = [];
      const notes: string[] = [];
      for (const grader of opts.graders()) {
        // Labels an AI wrote are not human agreement (ENG-2135); this baseline is labelled "human-label agreement".
        const cases = (await opts.store.listCases(grader.surface, { split: 'test' })).filter((c) => !isAiLabelled(c));
        const predictions = new Map<string, GraderPrediction>();
        // A grader that cannot read a case is an evaluator failure: the whole source fails closed.
        for (const c of cases) predictions.set(c.caseId, await grader.grade(c));
        const agreement = computeCriterionAgreement(cases, predictions, grader.primaryCriterion);
        if (!agreement.report) {
          notes.push(`${grader.graderId}: no labelled pairs on ${grader.primaryCriterion}`);
          continue;
        }
        const { n, observedAgreement } = agreement.report;
        observations.push({
          metricId: `golden-agreement:${grader.graderId}:${grader.primaryCriterion}`,
          graderId: grader.graderId,
          graderVersion: graderVersionOf(grader.graderId),
          kind: 'probabilistic',
          category: 'quality',
          n,
          passes: Math.round(observedAgreement * n),
          placeholder: false,
          failures: [],
        });
      }
      return { source: 'golden-set', status: 'ok', observations, notes };
    },
  };
}

/** ENG-1312 fixtures with real turns from the golden-set store where linked, else placeholders. */
export function storeBackedFixtureLoader(store: GoldenSetStore): () => Promise<LoadedReplayFixtures> {
  return () => loadReplayFixtures({ store });
}
